  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN,
};

const CANARY_INDICATORS = [
  'CANARY',
  'test',
  'dummy',
  'placeholder',
  'example',
  'fake',
  'invalid',
  'bad',
];

/**
 * Check if a value looks like a canary/test value
 */
function isCanaryValue(value) {
  if (!value) return false;
  const lowerValue = value.toLowerCase();
  return CANARY_INDICATORS.some(indicator => lowerValue.includes(indicator));
}

/**
 * Run a shell command with timeout
 */
function runCommand(cmd, args, timeoutMs = 5000) {
  return new Promise((resolve) => {
    const child = spawn(cmd, args, { 
      stdio: ['pipe', 'pipe', 'pipe'],
      env: { ...process.env, NODE_PATH: path.join(__dirname, '../node_modules') }
    });

    let output = '';
    let error = '';

    child.stdout.on('data', data => output += data.toString());
    child.stderr.on('data', data => error += data.toString());

    const timer = setTimeout(() => {
      child.kill('SIGTERM');
      resolve({ code: null, output, error, timedOut: true });
    }, timeoutMs);

    child.on('exit', (code, signal) => {
      clearTimeout(timer);
      resolve({ code, signal, output, error, timedOut: false });
    });

    // Send nothing to stdin
    child.stdin.end();
  });
}

